        r0=min(a for a,b in cells); c0=min(b for a,b in cells)
        r1=max(a for a,b in cells); c1=max(b for a,b in cells)
        h,w=r1-r0+1,c1-c0+1
        if is_hollow(g,r0,c0,h,w) and h>=3 and w>=3: t=0
        else: t=H-h
        for a,b in sorted(cells): O[t+a-r0][b]=c
    return O
