    from collections import deque
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                col=g[i][j]; comp=[]
                q=deque([(i,j)]); seen[i][j]=True
                while q:
                    x,y=q.popleft(); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and g[nx][ny]==col and not seen[nx][ny]:
