def greedy(inp):
    objs=[(c,cells) for c,cells in comps(inp)]
    H=len(inp);W=len(inp[0])
    pos={i:(min(r for r,_ in cells),min(c for _,c in cells)) for i,(c,cells) in enumerate(objs)}
    def bbox(i):
        r0,c0=pos[i]; h=max(r for r,_ in objs[i][1])-r0+1; w=max(c for _,c in objs[i][1])-c0+1
        return (r0,c0,h,w)
    changed=True
    while changed:
        changed=False
        occ=set()
        for i in pos:
            r0,c0,h,w=bbox(i)
            for rr in range(r0,r0+h):
                for cc in range(c0,c0+w): occ.add((rr,cc))
        for i in pos:
            r0,c0,h,w=bbox(i)
            cands=[]
            for j in pos:
                if j==i: continue
                r1,c1,h1,w1=bbox(j)
                colset=set(range(c0,c0+w)).intersection(set(range(c1,c1+w1)))
                if colset:
                    dr=min(max(0,r0-(r1+h1)+1),max(0,r1-r0-h+1))
                    cands.append((dr,'obj',j))
            cands+=[(H- (r0+h),'edge','top'),(r0,'edge','bot')]
            # choose closest candidate; tie: edge preferred? try variant below
            if cands:
                d,type_,tgt=min(cands,key=lambda z:(z[0],z[2]=='obj'))
                if type_=='obj':
                    nr=r0-(1 if d<=0 else 0)-1 if False else None
                    # nearest object vertical position of its bbox center
                    others=[pos[j] for j in [t] if t!=i]
                    tr=sum(p[0] for p in others)/len(others)
                    nr=r0 + (-1 if tr<r0 else 1)*max(1,(d//2 or 1))
                else:
                    nr=r0+(-1 if tgt=='top' else 1)*(d//2+1)
                if 0<=nr<H and not any((nr+dr2,cc) in occ for dr2 in [0] for cc in range(c0,c0+w)):
                    pos[i]=(nr,c0); changed=True
    return pos
